using System.Runtime.InteropServices;

class EnvVarCheck
{
    // P/Invoke to libc getenv — returns IntPtr.Zero only when the var is truly unset.
    [DllImport("libc", EntryPoint = "getenv", CharSet = CharSet.Ansi)]
    private static extern IntPtr NativeGetEnv(string name);

    static bool CheckEnvVarExistsOnLinux(string name) => NativeGetEnv(name) != IntPtr.Zero;

